using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change: discriminator property renamed to "$type".
            // Restore EF8 behavior so existing 500K documents remain readable.
            entity.HasDiscriminator<string>("Discriminator").HasValue("Product");

            // EF Core 9 breaking change: id format changed from "EntityType|Key" to just "Key".
            // Preserve EF8 id format so existing documents are found.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyCosmosIdGenerator>();

            // EF Core 9 removed support for client-side Cosmos indexes (HasIndex).
            // Indexes must be managed via Azure Portal/IaC on the container's indexing policy.
        });
    }
}

class Product
{
    public int Id { get; set; }
    public string Sku { get; set; }
}

// Generates ids in the EF8 format "Product|<key>" for backward compatibility.
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
        => $"Product|{entry.Property("Id").CurrentValue}";
}

